import express, { Request, Response, NextFunction } from 'express';
import crypto from 'crypto';

interface Document {
  id: string;
  title: string;
  content: string;
  owner: string;
  acl: string[];
  classification: 'public' | 'internal' | 'confidential';
}

interface SearchIndex {
  [normalizedTerm: string]: { docId: string; score: number }[];
}

const documents: Map<string, Document> = new Map();
const searchIndex: SearchIndex = {};
const userRoles: Map<string, string[]> = new Map();

// Initialize with sample data
userRoles.set('admin', ['admin', 'internal', 'confidential']);
userRoles.set('analyst', ['internal']);
userRoles.set('guest', ['public']);

// Require a strong, externally configured HMAC key. Fail closed if absent.
const HMAC_KEY = process.env.HMAC_KEY;
if (!HMAC_KEY || HMAC_KEY.length < 32) {
  throw new Error('HMAC_KEY environment variable must be set to a strong secret (>= 32 chars).');
}

function normalizeForIndex(term: string): string {
  // NFKC normalization for consistent indexing
  return term.normalize('NFKC').toLowerCase();
}

function normalizeForQuery(term: string): string {
  // NFKC normalization for broader query matching
  return term.normalize('NFKC').toLowerCase();
}

function tokenize(text: string): string[] {
  return text.split(/[\s\p{P}]+/u).filter(t => t.length > 0);
}

function buildIndexEntry(doc: Document): void {
  const terms = tokenize(doc.title + ' ' + doc.content);
  const termFreq: Map<string, number> = new Map();

  for (const term of terms) {
    const normalized = normalizeForIndex(term);
    termFreq.set(normalized, (termFreq.get(normalized) || 0) + 1);
  }

  for (const [term, freq] of termFreq) {
    if (!searchIndex[term]) {
      searchIndex[term] = [];
    }
    searchIndex[term].push({ docId: doc.id, score: freq });
  }
}

function checkAccess(userId: string, doc: Document): boolean {
  const roles = userRoles.get(userId) || [];
  if (roles.includes('admin')) return true;
  if (doc.classification === 'public') return true;
  if (doc.acl.includes(userId)) return true;
  if (doc.classification === 'internal' && roles.includes('internal')) return true;
  if (doc.classification === 'confidential' && roles.includes('confidential')) return true;
  return false;
}

function generateAccessSignature(userId: string, docId: string): string {
  return crypto.createHmac('sha256', HMAC_KEY as string)
    .update(`${userId}:${docId}`)
    .digest('hex').slice(0, 32);
}

function searchDocuments(query: string, userId: string): { results: Document[]; signature: string } {
  const queryTerms = tokenize(query);
  const docScores: Map<string, number> = new Map();

  for (const term of queryTerms) {
    const normalizedQuery = normalizeForQuery(term);

    // Search across all index entries
    for (const [indexedTerm, entries] of Object.entries(searchIndex)) {
      if (indexedTerm === normalizedQuery || indexedTerm.includes(normalizedQuery)) {
        for (const entry of entries) {
          docScores.set(entry.docId, (docScores.get(entry.docId) || 0) + entry.score);
        }
      }
    }
  }

  // Sort by score and apply access control
  const sortedDocs = [...docScores.entries()]
    .sort((a, b) => b[1] - a[1])
    .map(([docId]) => documents.get(docId)!)
    .filter(doc => doc !== undefined);

  // Access filtering happens AFTER scoring on the normalized results
  const accessibleDocs = sortedDocs.filter(doc => checkAccess(userId, doc));

  const sig = generateAccessSignature(userId, accessibleDocs.map(d => d.id).join(','));
  return { results: accessibleDocs, signature: sig };
}

const app = express();
app.use(express.json());

function authMiddleware(req: Request, res: Response, next: NextFunction): void {
  const userId = req.headers['x-user-id'] as string;
  if (!userId || !userRoles.has(userId)) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }
  (req as any).userId = userId;
  next();
}

app.post('/api/documents', authMiddleware, (req: Request, res: Response) => {
  const userId = (req as any).userId;
  const roles = userRoles.get(userId) || [];
  if (!roles.includes('admin')) {
    res.status(403).json({ error: 'Forbidden' });
    return;
  }

  const { title, content, classification, acl } = req.body;
  const id = crypto.randomUUID();
  const doc: Document = { id, title, content, owner: userId, acl: acl || [], classification };
  documents.set(id, doc);
  buildIndexEntry(doc);
  res.json({ id, message: 'Document indexed' });
});

app.get('/api/search', authMiddleware, (req: Request, res: Response) => {
  const userId = (req as any).userId;
  const query = req.query.q as string;

  if (!query || query.length > 200) {
    res.status(400).json({ error: 'Invalid query' });
    return;
  }

  const { results, signature } = searchDocuments(query, userId);

  res.json({
    results: results.map(doc => ({
      id: doc.id,
      title: doc.title,
      snippet: doc.content.substring(0, 150),
      classification: doc.classification
    })),
    resultCount: results.length,
    accessSignature: signature
  });
});

app.listen(3000, () => console.log('Search service running on :3000'));

export { app, searchDocuments, normalizeForIndex, normalizeForQuery, buildIndexEntry };
